/**
 * LuciProxy - Built-in HTML Template Assets
 * Safe base64 encoded static assets to prevent template literal interpolation collisions.
 */

function decodeBase64Utf8(b64) {
    try {
        if (typeof atob === "function") {
            const bin = atob(b64);
            const bytes = new Uint8Array(bin.length);
            for (let i = 0; i < bin.length; i++) {
                bytes[i] = bin.charCodeAt(i);
            }
            return new TextDecoder().decode(bytes);
        }
    } catch {}
    try {
        if (typeof Buffer !== "undefined") {
            return Buffer.from(b64, "base64").toString("utf-8");
        }
    } catch {}
    return "";
}

const DASHBOARD_B64 = "";
const SUBSCRIPTION_B64 = "";

let cachedDashboard = null;
let cachedSubscription = null;

export function getDashboardHtml() {
    if (!cachedDashboard) {
        cachedDashboard = decodeBase64Utf8(DASHBOARD_B64);
    }
    return cachedDashboard;
}

export function getSubscriptionHtml() {
    if (!cachedSubscription) {
        cachedSubscription = decodeBase64Utf8(SUBSCRIPTION_B64);
    }
    return cachedSubscription;
}
